def export():
    from cryptography.fernet import Fernet
    import json
    key = 'vdhOVlS0ghzlRy75aQLK0paoRHmWUvfoQ-EhWWx6D_o='
    filename = 'database.acddb'
    f = Fernet(key.encode('utf-8'))
    encrypted_data = f.encrypt(json.dumps(urlsdb).encode('utf-8'))
    with open(filename, "wb") as file:
        file.write(encrypted_data)

    file.close()
    print('finished exporting db.')

def export_supported_schools():
    schools = [school for school in urlsdb.keys()]
    with open('supported_schools.txt', "w") as file:
        for school in schools:
            file.write(school+'\n')

    file.close()
    print('finished exporting schools.')

export()
